import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: price list, single main items (new customer, first contract) ---
  it("quotes a sword for a new customer — base 100 G, +10 % first insurance, +5 G fee = 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("quotes an amulet for a new customer — base 60 G, +10 % first insurance, +5 G fee = 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("quotes a staff for a new customer — base 80 G, +10 % first insurance, +5 G fee = 93 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "staff", material: "oak", enchantment: 1, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it("quotes a potion for a new customer — base 40 G, +10 % first insurance, +5 G fee = 49 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "potion", material: "glass", enchantment: 0, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 49 }] });
  });

  // --- Quote: components and building blocks ---
  it.todo("quotes a single rune component — base 25 G, +10 % first insurance, +5 G fee = 33 G");
  it.todo("quotes a single moonstone component — base 25 G, +10 % first insurance, +5 G fee = 33 G");
  it.todo("quotes 3 alike runes as a building block — special base 60 G instead of 75 G, +10 %, +5 G fee = 71 G");
  it.todo("quotes 4 alike runes — building block 60 G + single 25 G = 85 G base, +10 %, +5 G fee = 99 G");
  it.todo("quotes 3 runes and 3 moonstones as two separate building blocks — base 120 G, +10 %, +5 G fee = 137 G");
  it.todo("does not form a building block from 3 unalike components — 2 runes + 1 moonstone = base 75 G, +10 %, +5 G fee = 88 G");

  // --- Quote: risk surcharges ---
  it.todo("adds a 50 % risk surcharge for a cursed sword — 150 G, +10 %, +5 G fee = 170 G");
  it.todo("adds a 30 % risk surcharge for a highly enchanted sword (enchantment 5) — 130 G, +10 %, +5 G fee = 148 G");
  it.todo("does not add the enchantment surcharge below level 5 (enchantment 4) — 100 G, +10 %, +5 G fee = 115 G");
  it.todo("combines cursed and high enchantment surcharges on one sword — 100 G × 1.8 = 180 G, +10 %, +5 G fee = 203 G");

  // --- Quote: customer modifiers ---
  it.todo("grants a 20 % loyalty discount for a customer with 2 years — sword 100 G × 0.8 = 80 G, +10 %, +5 G fee = 93 G");
  it.todo("does not grant the loyalty discount below 2 years (1 year) — sword 100 G, +10 %, +5 G fee = 115 G");
  it.todo("applies a 15 % discount on the second contract instead of the first-insurance surcharge — sword 100 G × 0.85 = 85 G, +5 G fee = 90 G");
  it.todo("applies the 15 % discount to the third contract as well — sword 100 G × 0.85 = 85 G, +5 G fee = 90 G");

  // --- Quote: rounding and combinations ---
  it.todo("rounds the premium up in MHPCO's favor — loyal customer's first cursed potion: 40 × 1.5 × 0.8 × 1.1 = 52.8 → 53, +5 G fee = 58 G");
  it.todo("quotes a mixed list of items in one contract — sword + amulet + 3 runes = 100 + 60 + 60 = 220 G, +10 %, +5 G fee = 247 G");

  // --- Claims: deductible ---
  it.todo("deducts the 100 G deductible from a single damage — 200 G damage on an amulet pays out 100 G");
  it.todo("pays out 0 G when the damage does not exceed the deductible — 100 G damage pays out 0 G");
  it.todo("applies the deductible once per damage event, not per damaged item — two 200 G damages in one incident pay out 300 G");

