  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const FIRST_INSURANCE_MULTIPLIER = 1.1;
const CONTRACT_FEE = 5;

const BUILDING_BLOCK_SIZE = 3;
const BUILDING_BLOCK_PRICE = 60;

const CURSED_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;

// Each surcharge adds a percentage of the base price when its condition holds.
// Rates add together, so a cursed and highly enchanted item pays 1 + 0.5 + 0.3.
const RISK_SURCHARGES: { appliesTo: (item: Item) => boolean; rate: number }[] = [
  { appliesTo: (item) => item.cursed === true, rate: CURSED_SURCHARGE_RATE },
  {
    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
  },
];

const totalSurchargeRateFor = (item: Item): number =>
  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
    (total, surcharge) => total + surcharge.rate,
    0,
  );

// Risk surcharges apply per item, before the contract-level multiplier and fee.
const riskAdjustedPriceOfItem = (item: Item): number =>
  BASE_PRICE_BY_TYPE[item.type] * (1 + totalSurchargeRateFor(item));

const sumOfIndividualPrices = (items: Item[]): number =>
  items.reduce((total, item) => total + riskAdjustedPriceOfItem(item), 0);

// "Alike" in the price list means same type — material and enchantment do not
// affect whether components group into a building block.
const groupByType = (items: Item[]): Item[][] => [
  ...items
    .reduce(
      (groups, item) =>
        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
      new Map<string, Item[]>(),
    )
    .values(),
];

// Every three alike components form a building block priced at 60 G; the
// remainder of the group is priced individually.
const priceOfAlikeGroup = (group: Item[]): number => {
  const blocks = Math.floor(group.length / BUILDING_BLOCK_SIZE);
  const leftovers = group.slice(blocks * BUILDING_BLOCK_SIZE);

  return blocks * BUILDING_BLOCK_PRICE + sumOfIndividualPrices(leftovers);
};

// The insured value of the whole list: price-list figures plus per-item risk
// surcharges, before any contract-level multiplier or fee.
const insuredValueOf = (items: Item[]): number =>
  groupByType(items).reduce((total, group) => total + priceOfAlikeGroup(group), 0);

const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT_RATE = 0.2;

const loyaltyMultiplierFor = (customer: Customer): number =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS ? 1 - LOYALTY_DISCOUNT_RATE : 1;

const REPEAT_CONTRACT_DISCOUNT_RATE = 0.15;

// A first insurance carries an assessment surcharge; every later contract
// earns the repeat-customer discount instead.
const repeatCustomerMultiplierFor = (precedingContracts: number): number =>
  precedingContracts === 0
    ? FIRST_INSURANCE_MULTIPLIER
    : 1 - REPEAT_CONTRACT_DISCOUNT_RATE;

// Customer-dependent factors that scale the whole contract, as opposed to the
// per-item risk surcharges already folded into the insured value.
const contractMultiplierFor = (
  customer: Customer,
  precedingContracts: number,
): number =>
  loyaltyMultiplierFor(customer) * repeatCustomerMultiplierFor(precedingContracts);

// Amounts are rounded up, in MHPCO's favor. The product is first snapped to
// six decimals so IEEE754 noise (100 × 1.1 = 110.00000000000001) does not
// push an exact amount to the next whole G.
const roundedUpInMHPCOsFavor = (amount: number): number =>
  Math.ceil(Number(amount.toFixed(6)));

const quoteStep = (
  step: QuoteStep,
  customer: Customer,
  precedingContracts: number,
): QuoteResult => ({
  premium:
    roundedUpInMHPCOsFavor(
      insuredValueOf(step.items) *
        contractMultiplierFor(customer, precedingContracts),
    ) + CONTRACT_FEE,
});

const DEDUCTIBLE = 100;
const CAP_FACTOR = 2;

const insuranceSumOf = (items: Item[]): number =>
  items.reduce((total, item) => total + INSURANCE_VALUE_BY_TYPE[item.type], 0);

const claimStep = (step: ClaimStep, steps: Step[]): ClaimResult => {
  const policy = steps[step.policy] as QuoteStep;
  const cap = CAP_FACTOR * insuranceSumOf(policy.items);
  const damage = step.incident.damages.reduce(
    (total, { amount }) => total + amount,
    0,
  );
  const payout = damage - DEDUCTIBLE;

  return { payout, remainingCap: cap - payout };
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step, index) =>
    step.op === "quote"
      ? quoteStep(step, scenario.customer, index)
      : claimStep(step, scenario.steps),
  ),
});

