  incident.damages.reduce((total, { amount }) => total + amount, 0);

const claimStep = (step: ClaimStep, steps: Step[]): ClaimResult => {
  const cap = CAP_FACTOR * coverSumOf(insuredItemsOf(step.policy, steps));
