// A claim names the quote step that created its policy. Resolving it by
// narrowing rather than casting means a mis-aimed index fails here, with the
// offending index in hand, instead of silently yielding NaN downstream.
const insuredItemsOf = (policyIndex: number, steps: Step[]): Item[] => {
  const policy = steps[policyIndex];

  if (policy?.op !== "quote") {
    throw new Error(`Step ${policyIndex} is not a quote step`);
  }

  return policy.items;
};

const totalDamageOf = (incident: Incident): number =>
  incident.damages.reduce((total, { amount }) => total + amount, 0);

const resultOfClaimStep = (step: ClaimStep, steps: Step[]): ClaimResult => {
  const cap = CAP_FACTOR * coverSumOf(insuredItemsOf(step.policy, steps));
  const payout = Math.max(0, totalDamageOf(step.incident) - DEDUCTIBLE);

  return { payout, remainingCap: cap - payout };
};

// TODO: a quote preceded only by claim steps is not a first contract, but the
// step index cannot tell the difference. No test distinguishes the two yet.
const isFirstContractAt = (stepIndex: number): boolean => stepIndex === 0;

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step, index) =>
    step.op === "quote"
      ? resultOfQuoteStep(step, scenario.customer, isFirstContractAt(index))
      : resultOfClaimStep(step, scenario.steps),
  ),
});

